/**
 * TodoMVC Vanilla JS App
 */
(function () {
  var STORAGE_KEY = 'todos-vanillajs';

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  var todos = getTodos();

  var todoListEl = document.getElementById('todo-list');
  var newTodoEl = document.querySelector('.new-todo');
  var toggleAllEl = document.getElementById('toggle-all');
  var mainEl = document.getElementById('main') || document.querySelector('.main');
  var footerEl = document.getElementById('footer') || document.querySelector('.footer');
  var counterEl = document.querySelector('.todo-count');
  var clearCompletedEl = document.querySelector('.clear-completed');
  var filtersEl = document.querySelector('.filters');

  function getRoute() {
    var hash = location.hash.replace(/^#/, '');
    if (hash === '/active') return 'active';
    if (hash === '/completed') return 'completed';
    return 'all';
  }

  /**
   * Saves a todo edit or destroys an empty/whitespace edit.
   * @planks("the user changes the edit input to {string} and presses Enter")
   * @planks("the user changes the edit input to {string} and the edit input loses focus")
   * @planks("the user clears the edit input and presses Enter")
   */
  function saveEdit(li, index) {
    var editInput = li.querySelector('.edit');
    var val = editInput.value.trim();
    if (val === '') {
      todos.splice(index, 1);
    } else {
      todos[index].title = val;
    }
    saveTodos(todos);
    render();
  }

  /**
   * Toggle a single todo between active and completed.
   * @planks("the user clicks the toggle checkbox for {string}")
   */
  function handleToggleTodo(index, checkbox) {
    todos[index].completed = checkbox.checked;
    saveTodos(todos);

    // Update the DOM row in place instead of rebuilding the whole list
    var li = checkbox.parentNode.parentNode;
    if (todos[index].completed) {
      li.classList.add('completed');
    } else {
      li.classList.remove('completed');
    }

    var route = getRoute();
    if (route === 'active' && todos[index].completed) {
      li.style.display = 'none';
    } else if (route === 'completed' && !todos[index].completed) {
      li.style.display = 'none';
    } else {
      li.style.display = '';
    }

    updateFooter();
  }

  /**
   * Enter edit mode for a todo by double-clicking the label.
   * @planks("the user double-clicks the label for {string}")
   */
  function handleDoubleClickLabel(li, editInput, title) {
    li.classList.add('editing');
    editInput.value = title;
    editInput.focus();
  }

  /**
   * Destroy a todo by clicking the destroy button.
   * @planks("the user clicks the destroy button for {string}")
   */
  function handleDestroyTodo(index) {
    todos.splice(index, 1);
    saveTodos(todos);
    render();
  }

  /**
   * Discard edit on pressing Escape.
   * @planks("the user changes the edit input to {string} and presses Escape")
   */
  function handleDiscardEdit(editInput, li, title) {
    li.classList.remove('editing');
    editInput.value = title;
  }

  /**
   * Update footer, counter, toggle-all, and filter highlight without rebuilding the list.
   */
  function updateFooter() {
    var activeCount = 0;
    var completedCount = 0;
    todos.forEach(function (todo) {
      if (todo.completed) completedCount++;
      else activeCount++;
    });

    var leftText = activeCount === 1 ? ' item left' : ' items left';
    counterEl.innerHTML = '<strong>' + activeCount + '</strong>' + leftText;

    if (todos.length === 0) {
      mainEl.style.display = 'none';
      footerEl.style.display = 'none';
    } else {
      mainEl.style.display = '';
      footerEl.style.display = '';
    }

    if (completedCount > 0) {
      clearCompletedEl.style.display = '';
    } else {
      clearCompletedEl.style.display = 'none';
    }

    if (todos.length > 0) {
      toggleAllEl.checked = todos.every(function (t) { return t.completed; });
    } else {
      toggleAllEl.checked = false;
    }

    var route = getRoute();
    var links = filtersEl.querySelectorAll('a');
    links.forEach(function (link) {
      var href = link.getAttribute('href').replace('#', '');
      link.classList.remove('selected');
      if (route === 'all' && href === '/') link.classList.add('selected');
      if (route === 'active' && href === '/active') link.classList.add('selected');
      if (route === 'completed' && href === '/completed') link.classList.add('selected');
    });
  }

  function render() {
    var route = getRoute();

    todoListEl.innerHTML = '';

    var activeCount = 0;
    var completedCount = 0;

    todos.forEach(function (todo, index) {
      if (todo.completed) {
        completedCount++;
      } else {
        activeCount++;
      }

      var visible = true;
      if (route === 'active' && todo.completed) visible = false;
      if (route === 'completed' && !todo.completed) visible = false;

      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');

      var viewDiv = document.createElement('div');
      viewDiv.classList.add('view');

      var checkbox = document.createElement('input');
      checkbox.classList.add('toggle');
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;
      checkbox.setAttribute('data-index', index);
      checkbox.addEventListener('change', function () {
        var idx = todos.indexOf(todo);
        handleToggleTodo(idx, checkbox);
      });

      var label = document.createElement('label');
      label.textContent = todo.title;
      label.addEventListener('dblclick', function () {
        handleDoubleClickLabel(li, editInput, todo.title);
      });

      var destroyBtn = document.createElement('button');
      destroyBtn.classList.add('destroy');
      destroyBtn.addEventListener('click', function () {
        var idx = todos.indexOf(todo);
        handleDestroyTodo(idx);
      });

      viewDiv.appendChild(checkbox);
      viewDiv.appendChild(label);
      viewDiv.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.classList.add('edit');
      editInput.value = todo.title;

      editInput.addEventListener('keypress', function (e) {
        if (e.key === 'Enter' || e.keyCode === 13) {
          saveEdit(li, index);
        }
      });

      editInput.addEventListener('blur', function () {
        if (li.classList.contains('editing')) {
          saveEdit(li, index);
        }
      });

      editInput.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' || e.keyCode === 27) {
          handleDiscardEdit(editInput, li, todo.title);
        }
      });

      li.appendChild(viewDiv);
      li.appendChild(editInput);

      if (!visible) {
        li.style.display = 'none';
      }

      todoListEl.appendChild(li);
    });

    updateFooter();
  }

  /**
   * Handle creating a new todo by typing in the input and pressing Enter.
   * @planks("the user types {string} in the new todo input and presses Enter")
   */
  function handleNewTodo() {
    newTodoEl.addEventListener('keypress', function (e) {
      if (e.key === 'Enter' || e.keyCode === 13) {
        var title = newTodoEl.value.trim();
        if (title === '') return;
        todos.push({
          id: String(Date.now() + Math.random()),
          title: title,
          completed: false
        });
        saveTodos(todos);
        newTodoEl.value = '';
        render();
      }
    });
  }

  /**
   * Handle toggling all todos complete or active.
   * @planks("the user clicks the toggle-all checkbox")
   */
  function handleToggleAll() {
    toggleAllEl.addEventListener('click', function () {
      var allCompleted = todos.every(function (t) { return t.completed; });
      var newCompleted = !allCompleted;
      todos.forEach(function (t) {
        t.completed = newCompleted;
      });
      saveTodos(todos);

      // Update every row in place instead of rebuilding the whole list
      var route = getRoute();
      var items = todoListEl.querySelectorAll('li');
      items.forEach(function (li) {
        var cb = li.querySelector('.toggle');
        cb.checked = newCompleted;
        if (newCompleted) {
          li.classList.add('completed');
        } else {
          li.classList.remove('completed');
        }
        if (route === 'active' && newCompleted) {
          li.style.display = 'none';
        } else if (route === 'completed' && !newCompleted) {
          li.style.display = 'none';
        } else {
          li.style.display = '';
        }
      });

      updateFooter();
    });
  }

  /**
   * Handle clearing completed todos.
   * @planks("the user clicks the clear completed button")
   */
  function handleClearCompleted() {
    clearCompletedEl.addEventListener('click', function () {
      todos = todos.filter(function (t) { return !t.completed; });
      saveTodos(todos);
      render();
    });
  }

  /**
   * Handle route changes for filtering todos.
   * @planks("the user navigates to {string}")
   * @planks("the current route is {string}")
   * @planks("the page is reloaded")
   */
  function handleRouting() {
    window.addEventListener('hashchange', function () {
      render();
    });
  }

  handleNewTodo();
  handleToggleAll();
  handleClearCompleted();
  handleRouting();

  render();
})();

/*
 * App-specific CSS overrides
 */

/* Hide controls while a row is being edited */
.todo-list li.editing .toggle,
.todo-list li.editing .destroy {
  display: none;
}

const { Given, When, Then, Before, After } = require('@cucumber/cucumber');
const assert = require('assert');

// --- Hooks ---

Before(async function () {
  // No-op; scenarios init app as needed
});

After(function () {
  this.teardown();
});

// --- Helpers ---

async function createTodo(world, title, completed) {
  const storage = world.window.localStorage;
  let todos = [];
  const raw = storage.getItem('todos-vanillajs');
  if (raw) {
    try { todos = JSON.parse(raw); } catch (e) { todos = []; }
  }
  todos.push({ id: String(Date.now() + Math.random()), title, completed: !!completed });
  storage.setItem('todos-vanillajs', JSON.stringify(todos));
  await world.initApp();
}

async function createTodos(world, names, completions) {
  const storage = world.window.localStorage;
  let todos = [];
  const raw = storage.getItem('todos-vanillajs');
  if (raw) {
    try { todos = JSON.parse(raw); } catch (e) { todos = []; }
  }
  let now = Date.now();
  for (let i = 0; i < names.length; i++) {
    todos.push({
      id: String(now + i + Math.random()),
      title: names[i],
      completed: completions ? completions[i] : false
    });
  }
  storage.setItem('todos-vanillajs', JSON.stringify(todos));
  await world.initApp();
}

function enterEditMode(world, title) {
  const li = world.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found for edit mode`);
  li.classList.add('editing');
  const editInput = li.querySelector('.edit');
  if (editInput) {
    editInput.value = title;
    editInput.focus();
  }
}

// ===================== GIVEN =====================

Given('the app is open', async function () {
  this._currentRoute = '';
  await this.initApp();
});

Given('the app is open with no todos', async function () {
  this._currentRoute = '';
  const storage = (this.window ? this.window : null);
  // Fresh init with empty localStorage
  this.teardown();
  await this.initApp();
});

Given('the todo {string} exists', async function (title) {
  await this.initApp();
  await createTodo(this, title, false);
});

Given('the todo {string} exists and is active', async function (title) {
  await this.initApp();
  await createTodo(this, title, false);
});

Given('the todo {string} exists and is completed', async function (title) {
  await this.initApp();
  await createTodo(this, title, true);
});

Given('the todos {string}, {string}, and {string} exist and are all active', async function (t1, t2, t3) {
  await this.initApp();
  await createTodos(this, [t1, t2, t3], [false, false, false]);
});

Given('the todos {string} and {string} exist and are all active', async function (t1, t2) {
  await this.initApp();
  await createTodos(this, [t1, t2], [false, false]);
});

Given('the todos {string} and {string} exist and are all completed', async function (t1, t2) {
  await this.initApp();
  await createTodos(this, [t1, t2], [true, true]);
});

Given('the todos {string}, {string}, and {string} exist and {string} is active and {string} is completed and {string} is completed', async function (t1, t2, t3, a1, a2, a3) {
  await this.initApp();
  await createTodos(this, [t1, t2, t3], [false, true, true]);
});

Given('the todos {string} and {string} exist and {string} is active and {string} is completed', async function (t1, t2, a1, a2) {
  await this.initApp();
  await createTodos(this, [t1, t2], [false, true]);
});

Given('the todos {string} and {string} exist and {string} is completed and {string} is active', async function (t1, t2, a1, a2) {
  await this.initApp();
  await createTodos(this, [t1, t2], [true, false]);
});

Given('the todo {string} is in edit mode', async function (title) {
  const storage = this.window ? this.window.localStorage : null;
  if (!this.window || !this.window.document.querySelector('#todo-list')) {
    await this.initApp();
    await createTodo(this, title, false);
  }
  enterEditMode(this, title);
});

Given('the todo {string} is in edit mode with input value {string}', async function (title, value) {
  if (!this.window || !this.window.document.querySelector('#todo-list li')) {
    await this.initApp();
    await createTodo(this, title, false);
  }
  enterEditMode(this, title);
  const li = this.findTodoElement(title);
  const editInput = li.querySelector('.edit');
  if (editInput) {
    editInput.value = value;
  }
});

Given('the todo {string} existed and was deleted', async function (title) {
  // Create a todo, add it to localStorage, then delete it
  await this.initApp();
  const storage = this.window.localStorage;
  // Just leave localStorage empty (todo was deleted)
  storage.setItem('todos-vanillajs', JSON.stringify([]));
  await this.initApp();
});

Given('the current route is {string}', function (route) {
  this._currentRoute = route;
  if (this.window) {
    this.window.location.hash = route;
  }
});

// ===================== WHEN =====================

When('the user types {string} in the new todo input and presses Enter', async function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'New todo input not found');
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  // Simulate Enter keypress
  const keyEvent = new this.window.Event('keypress', { bubbles: true });
  Object.defineProperty(keyEvent, 'key', { value: 'Enter' });
  Object.defineProperty(keyEvent, 'keyCode', { value: 13 });
  input.dispatchEvent(keyEvent);
  await this.tick();
});

Given('the todo list item element for {string} is captured', function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found for capture`);
  this._capturedLi = li;
});

When('the user clicks the toggle checkbox for {string}', async function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found`);
  const checkbox = li.querySelector('.toggle');
  assert.ok(checkbox, `Toggle checkbox not found for "${title}"`);
  checkbox.checked = !checkbox.checked;
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  await this.tick();
});

When('the user clicks the toggle-all checkbox', async function () {
  const checkbox = this.document.querySelector('#toggle-all');
  assert.ok(checkbox, 'Toggle-all checkbox not found');
  checkbox.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  await this.tick();
});

When('the user double-clicks the label for {string}', async function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found for double-click`);
  const label = li.querySelector('label');
  assert.ok(label, `Label not found for "${title}"`);
  const dblclick = new this.window.Event('dblclick', { bubbles: true });
  label.dispatchEvent(dblclick);
  await this.tick();
});

When('the user clicks the destroy button for {string}', async function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found for destroy`);
  const btn = li.querySelector('.destroy');
  assert.ok(btn, `Destroy button not found for "${title}"`);
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  await this.tick();
});

When('the user hovers over the todo {string}', function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found for hover`);
  // In real browsers, hover CSS makes .destroy visible
  // happy-dom doesn't run CSS, so we simulate the hover state
  li.classList.add('hovered');
  li.dispatchEvent(new this.window.Event('mouseover', { bubbles: true }));
});

When('the user clicks the clear completed button', async function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'Clear completed button not found');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  await this.tick();
});

When('the user navigates to {string}', async function (route) {
  this._currentRoute = route;
  this.window.location.hash = route;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
  await this.tick();
});

When('the user changes the edit input to {string} and presses Enter', async function (text) {
  const editingLi = this.document.querySelector('#todo-list li.editing');
  assert.ok(editingLi, 'No todo in edit mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  const keyEvent = new this.window.Event('keypress', { bubbles: true });
  Object.defineProperty(keyEvent, 'key', { value: 'Enter' });
  Object.defineProperty(keyEvent, 'keyCode', { value: 13 });
  editInput.dispatchEvent(keyEvent);
  await this.tick();
});

When('the user changes the edit input to {string} and the edit input loses focus', async function (text) {
  const editingLi = this.document.querySelector('#todo-list li.editing');
  assert.ok(editingLi, 'No todo in edit mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  await this.tick();
});

When('the user clears the edit input and presses Enter', async function () {
  const editingLi = this.document.querySelector('#todo-list li.editing');
  assert.ok(editingLi, 'No todo in edit mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  const keyEvent = new this.window.Event('keypress', { bubbles: true });
  Object.defineProperty(keyEvent, 'key', { value: 'Enter' });
  Object.defineProperty(keyEvent, 'keyCode', { value: 13 });
  editInput.dispatchEvent(keyEvent);
  await this.tick();
});

When('the user changes the edit input to {string} and presses Escape', async function (text) {
  const editingLi = this.document.querySelector('#todo-list li.editing');
  assert.ok(editingLi, 'No todo in edit mode');
  const editInput = editingLi.querySelector('.edit');
  assert.ok(editInput, 'Edit input not found');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  const keyEvent = new this.window.Event('keydown', { bubbles: true });
  Object.defineProperty(keyEvent, 'key', { value: 'Escape' });
  Object.defineProperty(keyEvent, 'keyCode', { value: 27 });
  editInput.dispatchEvent(keyEvent);
  await this.tick();
});

When('the page is reloaded', async function () {
  await this.reloadPage();
});

// ===================== THEN =====================

Then('a todo with title {string} appears in the todo list', function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found in list`);
});

Then('the todo {string} appears in the todo list', function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found in list`);
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'New todo input not found');
  assert.strictEqual(input.value, '');
});

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('#todo-list li');
  assert.strictEqual(items.length, 0, `Expected empty list but found ${items.length} items`);
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main') || this.document.querySelector('#main');
  assert.ok(main, 'Main section not found');
  const style = main.style.display;
  const classes = main.className;
  // hidden could be display:none or a class
  const isHidden = style === 'none' || classes.includes('hidden') || !main.offsetHeight && style;
  assert.ok(isHidden, 'Main section should be hidden');
});

Then('the footer section is hidden', function () {
  const footer = this.document.querySelector('.footer') || this.document.querySelector('#footer');
  assert.ok(footer, 'Footer section not found');
  const style = footer.style.display;
  const classes = footer.className;
  const isHidden = style === 'none' || classes.includes('hidden') || !footer.offsetHeight && style;
  assert.ok(isHidden, 'Footer section should be hidden');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main') || this.document.querySelector('#main');
  assert.ok(main, 'Main section not found');
  assert.notStrictEqual(main.style.display, 'none', 'Main section should not be display:none');
});

Then('the footer section is visible', function () {
  const footer = this.document.querySelector('.Footer') || this.document.querySelector('#footer') || this.document.querySelector('.footer');
  assert.ok(footer, 'Footer section not found');
  assert.notStrictEqual(footer.style.display, 'none', 'Footer section should not be display:none');
});

Then('the todo {string} is completed', function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found`);
  const checkbox = li.querySelector('.toggle');
  assert.ok(checkbox, `Toggle checkbox not found for "${title}"`);
  assert.ok(checkbox.checked, `Todo "${title}" should be completed`);
  assert.ok(li.classList.contains('completed') || li.className.includes('completed'),
    `Todo "${title}" li should have class "completed"`);
});

Then('the todo {string} is not completed', function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found`);
  const checkbox = li.querySelector('.toggle');
  assert.ok(checkbox, `Toggle checkbox not found for "${title}"`);
  assert.ok(!checkbox.checked, `Todo "${title}" should not be completed`);
});

Then('the new todo {string} is not completed', function (title) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found`);
  const checkbox = li.querySelector('.toggle');
  assert.ok(checkbox, `Toggle checkbox not found for "${title}"`);
  assert.ok(!checkbox.checked, `New todo "${title}" should not be completed`);
});

Then('the todo list item for {string} has the class {string}', function (title, cls) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found`);
  assert.ok(li.classList.contains(cls), `Todo "${title}" should have class "${cls}" but has "${li.className}"`);
});

Then('the todo list item for {string} does not have the class {string}', function (title, cls) {
  const li = this.findTodoElement(title);
  assert.ok(li, `Todo "${title}" not found`);
  assert.ok(!li.classList.contains(cls), `Todo "${title}" should not have class "${cls}"`);
});

Then('the todo list item does not have the class {string}', function (cls) {
  // Refers to any todo in edit mode or the first/only todo
  const editingLi = this.document.querySelector('#todo-list li.editing');
  const items = this.document.querySelectorAll('#todo-list li');
  // Check all items do not have the class
  for (const item of items) {
    if (item.classList.contains(cls)) {
