const { setDefaultTimeout, setWorldConstructor, World } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');
const vm = require('vm');

setDefaultTimeout(5000);

const TODOAPP_HTML = `
  <section class="todoapp">
    <header class="header">
      <h1>todos</h1>
      <input class="new-todo" placeholder="What needs to be done?">
    </header>
    <section class="main" id="main">
      <input id="toggle-all" type="checkbox">
      <label for="toggle-all">Mark all as complete</label>
      <ul id="todo-list"></ul>
    </section>
    <footer class="footer" id="footer">
      <span class="todo-count"><strong>0</strong> items left</span>
      <ul class="filters">
        <li><a href="#/">All</a></li>
        <li><a href="#/active">Active</a></li>
        <li><a href="#/completed">Completed</a></li>
      </ul>
      <button class="clear-completed">Clear completed</button>
    </footer>
  </section>
`;

function makeContext(win, doc) {
  return vm.createContext({
    window: win,
    document: doc,
    localStorage: win.localStorage,
    console: console,
    setTimeout: (fn, ms) => { fn(); return 0; },
    setInterval: () => 0,
    clearTimeout: () => {},
    clearInterval: () => {},
    location: win.location,
    addEventListener: win.addEventListener.bind(win),
    removeEventListener: win.removeEventListener.bind(win),
    dispatchEvent: win.dispatchEvent.bind(win),
    Event: win.Event,
    CustomEvent: win.CustomEvent,
    HTMLElement: win.HTMLElement,
    navigator: win.navigator,
  });
}

function loadApp(win, doc) {
  const appPath = path.join(process.cwd(), 'js', 'app.js');
  if (fs.existsSync(appPath)) {
    const appCode = fs.readFileSync(appPath, 'utf8');
    const context = makeContext(win, doc);
    vm.runInContext(appCode, context);
  }
}

class TodoWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
    this._savedStorage = {};
    this._currentRoute = '';
  }

  async initApp() {
    // Save storage from existing window before teardown
    if (this.window) {
      this._saveStorage(this.window);
    }
    this.teardown();

    this.window = new Window({ url: 'http://localhost/', width: 1024, height: 768 });
    this.document = this.window.document;
    this.document.body.innerHTML = TODOAPP_HTML;

    // Restore saved storage
    this._restoreStorage(this.window);

    // Set route
    if (this._currentRoute) {
      this.window.location.hash = this._currentRoute;
    }

    // Load app
    loadApp(this.window, this.document);

    await this.tick();
  }

  _saveStorage(win) {
    this._savedStorage = {};
    for (let i = 0; i < win.localStorage.length; i++) {
      const key = win.localStorage.key(i);
      this._savedStorage[key] = win.localStorage.getItem(key);
    }
  }

  _restoreStorage(win) {
    for (const key of Object.keys(this._savedStorage)) {
      win.localStorage.setItem(key, this._savedStorage[key]);
    }
  }

  async tick() {
    await new Promise(resolve => setTimeout(resolve, 50));
  }

  async reloadPage() {
    // Save localStorage state from current window
    this._saveStorage(this.window);
    const savedRoute = this._currentRoute || '';

    // Close old window
    this.teardown();

    // Create new window and restore storage
    this.window = new Window({ url: 'http://localhost/', width: 1024, height: 768 });
    this.document = this.window.document;
    this._restoreStorage(this.window);

    // Restore route
    this.window.location.hash = savedRoute;

    this.document.body.innerHTML = TODOAPP_HTML;

    // Load app
    loadApp(this.window, this.document);

    await this.tick();
  }

  findTodoElement(title) {
    const items = this.document.querySelectorAll('#todo-list li');
    for (const item of items) {
      const label = item.querySelector('label');
      if (label && label.textContent.trim() === title) {
        return item;
      }
    }
    return null;
  }

  teardown() {
    if (this.window) {
      this.window.close();
      this.window = null;
      this.document = null;
    }
  }
}

setWorldConstructor(TodoWorld);

