edits.newText:
toggleAllEl.addEventListener('click', function () {
  var allCompleted = todos.every(function (t) { return t.completed; });
  var newCompleted = !allCompleted;
  todos.forEach(function (t) {
    t.completed = newCompleted;
  });
  saveTodos(todos);

  // Update every row in place instead of rebuilding the whole list
  var route = getRoute();
  var items = todoListEl.querySelectorAll('li');
  items.forEach(function (li) {
    var cb = li.querySelector('.toggle');
    cb.checked = newCompleted;
    if (newCompleted) {
      li.classList.add('completed');
    } else {
      li.classList.remove('completed');
    }
    if (route === 'active' && newCompleted) {
      li.style.display = 'none';
    } else if (route === 'completed' && !newCompleted) {
      li.style.display = 'none';
    } else {
      li.style.display = '';
    }
  });

  updateFooter();
});

